#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<long long> blockSums(max_threads, 0LL);
    std::vector<long long> blockOffsets(max_threads, 0LL);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const int chunk = (n + nt - 1) / nt;
        const int begin = tid * chunk;
        int end = begin + chunk;
        if (end > n) end = n;

        long long localSum = 0;
        if (begin < n) {
            for (int i = begin; i < end; ++i) {
                localSum += x[i];
                output[i] = static_cast<int>(localSum);
            }
        }

        blockSums[tid] = localSum;

        #pragma omp barrier

        #pragma omp single
        {
            long long running = 0;
            for (int t = 0; t < nt; ++t) {
                blockOffsets[t] = running;
                running += blockSums[t];
            }
        }

        #pragma omp barrier

        const long long offset = blockOffsets[tid];
        if (begin < n && offset != 0) {
            for (int i = begin; i < end; ++i) {
                output[i] = static_cast<int>(output[i] + offset);
            }
        }
    }
}
